mapper.sql:
where 1=1

		and cepr_llave = #{llaveTabla}


		and cepr_estado = #{estado}


		and cepr_codigo = #{codigo}


		and cepr_grupo = #{grupo}


		and cepr_tipo = #{tipo}


		and cepr_restriccion = #{restriccion}


		and (upper(cepr_nombre) like upper('%' || #{filtroParametro} || '%') or upper(cepr_codigo) like upper('%' || #{filtroParametro} || '%'))

mapper.select:
where cepr_estado = 'A'
and cepr_grupo = #{grupo}
and (cepr_restriccion is null or cepr_restriccion in ( select grado.cpvc_valoropcion from campo_documento grado, campo_documento estudiante, usuariorol_erlp, usuariosesion_ussp where grado.cdrc_documento = estudiante.cpvc_valoropcion and estudiante.cdrc_documento = cerl_documento and cerl_usuario = cuss_usuario and cuss_llave = #{securityToken} and cerl_estado = 'A' and cerl_rolacceso = (select cenc_rol from encuestagrupo_egrp, encuesta_encp where cegr_encuesta = cenc_llave and cegr_llave = #{grupo}) )) order by cepr_codigo , cepr_nombre
